INSERT INTO `faqs` (`uuid`, `pertanyaan`, `jawaban`, `urutan`, `status`, `created_at`, `updated_at`) VALUES
('4b9411a3-ccc5-44fd-bc24-e8dc7065773c', 'Bagaimana proses penerimaan siswa baru di SLB? Apakah ada tes atau asesmen khusus?', 'Salah satu persyaratan yaitu melakukan Tes IQ terlebih dahulu dan akan dilakukan asesmen khusus juga di sekolah.', 2, 'active', '2025-09-17 20:19:23', '2025-09-17 20:19:23'),
('6bb623f8-916a-436b-85b3-a57035fe5ac5', 'Bagaimana metode pembelajaran di SLB, apakah berbeda dengan sekolah reguler?', 'Kurikulum di SLB Patriot Kota Bekasi sama dengan sekolah lain pada umumnya, hanya saja keluasan dan tingkat kesulitan materinya yang disesuaikan dengan kemampuan siswa.', 4, 'active', '2025-09-17 20:20:44', '2025-09-17 20:20:44'),
('95b200f1-69c7-4f1b-a76b-172bcf5fcc55', 'Bagaimana dengan pembiayaan di sekolah ini?', 'Pembiayaan ada 2 jenis yaitu :\r\n1. Biaya masuk sebesar Rp. 2.500.000,- dan\r\n2. IPP (Iuran Pendanaan Pendidikan) per bulan sebesar Rp. 400.000,-', 5, 'active', '2025-09-17 20:21:00', '2026-05-24 18:37:17'),
('fa2b17f9-f0d4-4849-8373-8d787b80113e', 'Sekolah ini menerima jenis kekhususan apa saja?', 'Tunanetra (A), Tunagrahita (C), Tunadaksa (D) dan Autis.', 1, 'active', '2025-09-17 20:13:33', '2025-09-17 20:19:06'),
('fd90f57c-53aa-4b5d-8e11-faea4808686d', 'Apa saja fasilitas dan layanan yang tersedia di sekolah untuk mendukung kebutuhan anak saya?', 'Ada berbagai kegiatan baik intrakurikuler maupun ektrakuriler yang ada di SLB Patriot Kota Bekasi diantaranya Band, Hadroh, Degung, Melukis, BTQ, Pramuka, Baca Tulis, Tenis Meja dan Vocal.', 3, 'active', '2025-09-17 20:20:22', '2025-09-17 20:20:22');

