INSERT INTO `testimonials` (`uuid`, `nama`, `jabatan`, `isi_testimoni`, `foto`, `urutan`, `is_active`, `created_at`, `updated_at`) VALUES
('9549e779-f92b-4acd-abdd-9c2dc4b32852', 'Rina', 'Ibu rumah Tangga', 'SLB Patriot memberikan pendidikan yang luar biasa bagi anak saya. Guru-gurunya sangat peduli dan selalu mendukung perkembangan anak.', 'testimoni/HmRPWNJOUmGfWXIMy12HWPaeqnbMPCiopSRf0ObI.webp', 1, 'active', '2025-09-30 03:44:10', '2025-09-30 03:44:10'),
('9d590444-dd96-4ead-9373-c53aa391c92d', 'Anton', 'PNS', 'Karena anak-anak itu bisa dan merekam memori yang ada, mungkin mereka tidak bisa mempraktekkan di depan ibu- ibunya,tetapi dihati mereka sudah bisa dilaksanakan, juga untuk anak – anak didik saya dengan moment seperti ini mereka juga lebih percaya diri kedepannya', 'testimoni/GuFL9Ofc5P7rPBF5Y4xQh1p5sbO2mPdLbnkuVmvt.png', 4, 'active', '2025-09-30 03:59:14', '2025-09-30 03:59:14'),
('ab444a7d-7b67-4f80-8898-56534c767569', 'Wilda', 'Dokter', 'Semoga kedepannya anak- anak lebih baik dan mandiri, karena kelak kita tidak akan selamanya mendampingi, sehingga mereka harus mandiri, dan sebagai orang tua harus sabar dan ikhlas memiliki anak yang berkebutuhan khusus', 'testimoni/TXPbTKjMkeR6ePc3kCpXsyEsJZ1ZI1nPdlbzniRf.webp', 3, 'active', '2025-09-30 03:57:57', '2025-09-30 03:57:57'),
('d58049b0-79ed-49b3-82f5-6d9ee63b8145', 'Adi', 'Wiraswasta', 'Para gurunya sangat komunikatif, tidak segan menghubungi orang tua bila ada perkembangan penting. Saya merasa dilibatkan dalam proses pendidikan anak saya', 'testimoni/t98frFewLHGcph1xJnxGayMbUxDPUeGTHdvT0lF3.png', 2, 'active', '2025-09-30 03:53:55', '2025-09-30 03:53:55');

